import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

class KeyValueStore {
    private final ConcurrentHashMap<String, String> store = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, AtomicLong> accessCounts = new ConcurrentHashMap<>();

    public void put(String key, String value) {
        if (key == null) {
            throw new IllegalArgumentException();
        }
        store.put(key, value);
        accessCounts.putIfAbsent(key, new AtomicLong(0));
    }

    public String get(String key) {
        if (key == null) {
            throw new IllegalArgumentException();
        }
        accessCounts.computeIfAbsent(key, k -> new AtomicLong(0)).incrementAndGet();
        return store.get(key);
    }

    public long getAccessCount(String key) {
        if (key == null) {
            throw new IllegalArgumentException();
        }
        AtomicLong count = accessCounts.get(key);
        return count != null ? count.get() : 0;
    }
}

