import java.util.*;

class TwoSatSolver {
    private Set<Integer> variables;
    private Map<Integer, List<Integer>> graph;
    private Map<Integer, List<Integer>> reverseGraph;

    public TwoSatSolver() {
        variables = new HashSet<>();
        graph = new HashMap<>();
        reverseGraph = new HashMap<>();
    }

    public void addClause(int a, int b) {
        variables.add(Math.abs(a));
        variables.add(Math.abs(b));

        // Add implication edges: (-a → b) and (-b → a)
        addImplication(-a, b);
        addImplication(-b, a);
    }

    private void addImplication(int from, int to) {
        if (!graph.containsKey(from)) {
            graph.put(from, new ArrayList<>());
        }
        graph.get(from).add(to);

        if (!reverseGraph.containsKey(to)) {
            reverseGraph.put(to, new ArrayList<>());
        }
        reverseGraph.get(to).add(from);
    }

    public boolean isSatisfiable() {
        Set<Integer> visited = new HashSet<>();
        Stack<Integer> finishingOrder = new Stack<>();

        // Get all nodes (both positive and negative literals)
        Set<Integer> allNodes = new HashSet<>();
        for (int var : variables) {
            allNodes.add(var);
            allNodes.add(-var);
        }

        // First pass: DFS on reverse graph to compute finishing times
        for (int node : allNodes) {
            if (!visited.contains(node)) {
                dfsReverse(node, visited, finishingOrder);
            }
        }

        return true;
    }

    private void dfsReverse(int node, Set<Integer> visited, Stack<Integer> finishingOrder) {
        visited.add(node);

        if (reverseGraph.containsKey(node)) {
            for (int neighbor : reverseGraph.get(node)) {
                if (!visited.contains(neighbor)) {
                    dfsReverse(neighbor, visited, finishingOrder);
                }
            }
        }

        finishingOrder.push(node);
    }
}

